3.2 create_events_and_times_1_11
Creates event_hosp_1–event_hosp_11 and time_to_event_hosp_1–time_to_event_hosp_11 from hosp_visit_0_* (baseline) and extra hosp_visit_1_*–hosp_visit_5_* rows.


Code
create_events_and_times_1_11 &lt;- function(data) {
    # Initialize hospital event and time variables
    for (i in 1:11) {
        data[[paste0("event_hosp_", i)]] &lt;- 0
        data[[paste0("time_to_event_hosp_", i)]] &lt;- NA
    }

    # Process each row
    for (i in seq_len(nrow(data))) {
        # If baseline hospital visit is missing, set all to 0/NA
        if (is.na(data[i, "hosp_visit_0_diff"])) {
            for (j in 1:11) {
                data[i, paste0("event_hosp_", j)] &lt;- 0
                data[i, paste0("time_to_event_hosp_", j)] &lt;- NA
            }
        } else {
            # Baseline hospital visit
            for (j in 1:11) {
                if (!is.na(data[i, paste0("hosp_visit_0_reason_", j)]) &&
                    data[i, paste0("hosp_visit_0_reason_", j)] == 1) {
                    data[i, paste0("event_hosp_", j)] &lt;- 1
                    data[i, paste0("time_to_event_hosp_", j)] &lt;- data[i, "hosp_visit_0_diff"]
                }
            }
        }

        # Additional hospital visits
        if (!is.na(data[i, "other_hosp"]) && data[i, "other_hosp"] == 1) {
            extra_hosp_n &lt;- as.numeric(data[i, "extra_hosp_n"])
            if (!is.na(extra_hosp_n) && extra_hosp_n &gt; 0) {
                for (visit in 1:extra_hosp_n) {
                    for (j in 1:11) {
                        if (!is.na(data[i, paste0("event_hosp_", j)]) &&
                            data[i, paste0("event_hosp_", j)] == 0 &&
                            !is.na(data[i, paste0("hosp_visit_", visit, "_reason_", j)]) &&
                            data[i, paste0("hosp_visit_", visit, "_reason_", j)] == 1) {
                            data[i, paste0("event_hosp_", j)] &lt;- 1
                            data[i, paste0("time_to_event_hosp_", j)] &lt;- data[i, paste0("hosp_visit_", visit, "_diff")]
                        }
                    }
                }
            }
        }
    }

    return(data)
}

3.7 dia_list_name
Identifies patients with a given diagnosis (and optionally medication) on or before index_date. Supports excluding specific diagnosis name strings.


Code
dia_list_name &lt;- function(data, listed_names, index_date, excluded_names = NULL, med_data = NULL, med_names = NULL) {
  #
  if (!is.null(excluded_names)) {
    excluded_pattern &lt;- paste(
      gsub("([][()])", "\\\\\\1", excluded_names),  #
      collapse = "|"
    )
  }

  if (is.null(excluded_names)) {
    dia_result &lt;- data %&gt;%
      filter(Date &lt;= {{index_date}}) %&gt;%
      filter(grepl(paste(listed_names, collapse = "|"), Diagnosis_Name, ignore.case = TRUE)) %&gt;%
      distinct(EMPI)
  } else {
    dia_result &lt;- data %&gt;%
      filter(Date &lt;= {{index_date}}) %&gt;%
      filter(
        grepl(paste(listed_names, collapse = "|"), Diagnosis_Name, ignore.case = TRUE),
        !grepl(excluded_pattern, Diagnosis_Name, ignore.case = TRUE)  #
      ) %&gt;%
      distinct(EMPI)
  }

  if (!is.null(med_data)) {
    med_result &lt;- med_data %&gt;%
      filter(Medication_Date &lt;= {{index_date}}) %&gt;%
      filter(grepl(paste(med_names, collapse = "|"), Medication, ignore.case = TRUE)) %&gt;%
      distinct(EMPI)
  } else {
    med_result &lt;- NULL
  }

  final_result &lt;- rbind(dia_result, med_result) %&gt;%
    distinct(EMPI)

  return(final_result)
}

3.8 dia_list_icd / dia_list_icd_after_index
Ported unchanged from the ICI-CKD project (Kavita ICI CKD/data_management.qmd §3.6). dia_list_icd returns patients with a matching ICD code on or before the index date (baseline comorbidity); dia_list_icd_after_index returns the first date after the index date (outcome).


Code
dia_list_icd &lt;- function(data, index_date, icd_code,
                         excluded_names = NULL, med_data = NULL, med_names = NULL) {
  if (is.null(excluded_names)) {
    dia_result &lt;- data %&gt;%
      filter(Date &lt;= {{index_date}}) %&gt;%
      filter(grepl(paste(icd_code, collapse = "|"), Code, ignore.case = TRUE)) %&gt;%
      distinct(EMPI)
  } else {
    dia_result &lt;- data %&gt;%
      filter(Date &lt;= {{index_date}}) %&gt;%
      filter(grepl(paste(icd_code, collapse = "|"), Code, ignore.case = TRUE),
            !grepl(paste(excluded_names, collapse = "|"), Diagnosis_Name, ignore.case = TRUE)) %&gt;%
      distinct(EMPI)
  }

  if (!is.null(med_data)) {
    med_result &lt;- med_data %&gt;%
      filter(Medication_Date &lt;= {{index_date}}) %&gt;%
      filter(grepl(paste(med_names, collapse = "|"), Medication, ignore.case = TRUE)) %&gt;%
      distinct(EMPI)
  } else {
    med_result &lt;- NULL
  }

  rbind(dia_result, med_result) %&gt;% distinct(EMPI)
}




Code
dia_list_icd_after_index &lt;- function(data, index_date, icd_code,
                                     excluded_names = NULL,
                                     med_data = NULL, med_names = NULL) {
  dia_subset &lt;- data %&gt;%
    filter(Date &gt; {{index_date}}) %&gt;%
    filter(grepl(paste(icd_code, collapse = "|"), Code, ignore.case = TRUE))

  if (!is.null(excluded_names)) {
    dia_subset &lt;- dia_subset %&gt;%
      filter(!grepl(paste(excluded_names, collapse = "|"), Diagnosis_Name, ignore.case = TRUE))
  }

  dia_result &lt;- dia_subset %&gt;%
    group_by(EMPI) %&gt;%
    summarise(event_date = min(Date), .groups = "drop")

  med_result &lt;- NULL
  if (!is.null(med_data) && !is.null(med_names)) {
    med_result &lt;- med_data %&gt;%
      filter(Medication_Date &gt; {{index_date}}) %&gt;%
      filter(grepl(paste(med_names, collapse = "|"), Medication, ignore.case = TRUE)) %&gt;%
      group_by(EMPI) %&gt;%
      summarise(event_date = min(Medication_Date), .groups = "drop")
  }

  bind_rows(dia_result, med_result) %&gt;%
    group_by(EMPI) %&gt;%
    summarise(first_event_date = min(event_date), .groups = "drop")
}

3.11 get_ckd_stage — numeric KDIGO stage
Ported unchanged from ICI-CKD §3.3. Returns 1–5 rather than the labelled factor used for Table 1 (ckd_stage_cre / ckd_stage_cre_cys), because the CKD outcome logic below compares stages numerically.


Code
get_ckd_stage &lt;- function(egfr) {
  if (is.na(egfr))      return(NA)
  else if (egfr &gt;= 90)  return(1)
  else if (egfr &gt;= 60)  return(2)
  else if (egfr &gt;= 30)  return(3)
  else if (egfr &gt;= 15)  return(4)
  else                  return(5)
}

4.4 Create platinum-related side_effect variable (hosp reasons 1–7)


Code
# side_effect = 1 if any of hosp reasons 1–7 (platinum-associated AEs) occurred
side_effect &lt;- master %&gt;%
  select(record_id, matches("^event_hosp_[1-7]$|^time_to_event_hosp_[1-7]$")) %&gt;%
  rowwise() %&gt;%
  mutate(
    side_effect = if_else(any(c_across(starts_with("event_hosp_")) == 1, na.rm = TRUE), 1, 0),
    time_to_side_effect = {
      if (side_effect == 1) {
        times &lt;- c_across(starts_with("time_to_event_hosp_"))[c_across(starts_with("event_hosp_")) == 1]
        if (any(!is.na(times))) min(times, na.rm = TRUE) else NA_real_
      } else {
        NA_real_
      }
    }
  ) %&gt;%
  ungroup() %&gt;% select(record_id, side_effect, time_to_side_effect)

# Censor at 90 days
side_effect &lt;- side_effect %&gt;% mutate(
  side_effect = case_when(
    side_effect == 1 & time_to_side_effect &gt; 90 ~ 0,
    TRUE ~ side_effect
  ),
  time_to_side_effect = case_when(
    side_effect == 1 & time_to_side_effect &gt; 90 ~ 90,
    side_effect == 0 ~ 90,
    TRUE ~ time_to_side_effect
  )
)

4.4b Create overall hospitalization variable (any reason 1–11)


Code
# any_hosp = 1 if hospitalized for ANY reason (1–11) within 90 days
overall_hosp &lt;- master %&gt;%
  select(record_id, matches("^event_hosp_\\d+$"), matches("^time_to_event_hosp_\\d+$")) %&gt;%
  rowwise() %&gt;%
  mutate(
    any_hosp = if_else(any(c_across(starts_with("event_hosp_")) == 1, na.rm = TRUE), 1, 0),
    time_to_any_hosp = {
      if (any_hosp == 1) {
        events &lt;- c_across(starts_with("event_hosp_"))
        times  &lt;- c_across(starts_with("time_to_event_hosp_"))
        valid  &lt;- which(events == 1 & !is.na(times))
        if (length(valid) &gt; 0) min(times[valid], na.rm = TRUE) else NA_real_
      } else {
        NA_real_
      }
    }
  ) %&gt;%
  ungroup() %&gt;% select(record_id, any_hosp, time_to_any_hosp)

# Censor at 90 days
overall_hosp &lt;- overall_hosp %&gt;% mutate(
  any_hosp = case_when(
    any_hosp == 1 & time_to_any_hosp &gt; 90 ~ 0,
    TRUE ~ any_hosp
  ),
  time_to_any_hosp = case_when(
    any_hosp == 1 & time_to_any_hosp &gt; 90 ~ 90,
    any_hosp == 0 ~ 90,
    TRUE ~ time_to_any_hosp
  )
)

